B.push(
{id:"M4-01",m:4,q:"¿Qué representa el Valor Actual Neto (VAN) en el análisis de inversiones?",o:["La diferencia entre el valor presente de los flujos y la inversión inicial","La tasa que iguala los flujos a la inversión inicial","La suma nominal de los flujos futuros","El plazo de recupero de la inversión"],a:0,e:"VAN = valor presente de los flujos − inversión inicial. La TIR es la tasa que hace VAN = 0.",r:"M4 · P1"},
{id:"M4-02",m:4,q:"¿Qué indica la Tasa Interna de Retorno (TIR)?",o:["La tasa que iguala el VAN a cero","La tasa libre de riesgo del mercado","El rendimiento garantizado de la inversión","La tasa de descuento fijada por el inversor"],a:0,e:"TIR: la tasa de descuento que anula el VAN.",r:"M4 · P2"},
{id:"M4-04",m:4,q:"¿Cuál es una característica principal de los instrumentos de renta fija?",o:["Pago de intereses preestablecidos y vencimiento definido","Participación en las utilidades del emisor","Derecho a voto en la asamblea","Rendimiento variable según el resultado del ejercicio"],a:0,e:"Flujo conocido de antemano y fecha de vencimiento cierta.",r:"M4 · P3"},
{id:"M4-05",m:4,q:"¿Cuál de los siguientes es un riesgo asociado a la renta fija?",o:["Riesgo de dilución","Riesgo de gobierno corporativo","Riesgo de reinversión","Riesgo de iliquidez del accionista"],a:2,e:"Los riesgos típicos de renta fija: precio, reinversión, crédito, liquidez y tipo de cambio.",r:"M4 · P4"},
{id:"M4-113",m:4,q:"¿Qué norma establece las condiciones de emisión de obligaciones negociables?",o:["Ley 24.083","Ley 27.440","Ley 23.576","Ley 24.441"],a:2,e:"La Ley 23.576 es la Ley de Obligaciones Negociables: ahí están sus condiciones de emisión.",r:"M4 · P5"},
{id:"M4-03",m:4,q:"¿Cuál de los siguientes factores afecta directamente el cálculo del VAN?",o:["La cantidad de acciones en circulación","La tasa de descuento aplicada a los flujos futuros","El valor nominal del capital social","La cotización de cierre del período anterior"],a:1,e:"A mayor tasa de descuento, menor valor presente de los flujos y menor VAN.",r:"M4 · P6"},
{id:"M4-06",m:4,q:"¿Qué representa el análisis fundamental en renta variable?",o:["La predicción de precios mediante patrones gráficos","El cálculo del margen de garantía exigido","La medición de la volatilidad implícita","La evaluación de estados financieros y factores económicos"],a:3,e:"Fundamental: valor intrínseco a partir de balances y contexto. Técnico: precios y volúmenes históricos.",r:"M4 · P7"},
{id:"M4-07",m:4,q:"¿Cuál es el objetivo del análisis técnico?",o:["Predecir movimientos futuros del precio mediante patrones históricos","Determinar el valor intrínseco de la empresa","Evaluar la calidad crediticia del emisor","Calcular el VAN de un proyecto"],a:0,e:"El análisis técnico trabaja sobre el precio y su historia, no sobre los fundamentos de la empresa.",r:"M4 · P8"},
{id:"M4-08",m:4,q:"¿Qué mide el ratio PER (Price Earnings Ratio)?",o:["La relación entre el precio de la acción y la ganancia por acción","La relación entre el precio y el valor libro","El dividendo sobre el precio de la acción","El endeudamiento sobre el patrimonio neto"],a:0,e:"PER = precio / ganancia por acción: cuántas veces se paga la ganancia de la empresa.",r:"M4 · P9"},
{id:"M4-61",m:4,q:"¿Cuál es un componente clave en la formación del precio de las acciones?",o:["El precio de referencia que fija la CNV para cada especie listada","El valor nominal de la acción","La interacción entre oferta y demanda en el mercado","La tasa de cupón del último dividendo"],a:2,e:"El precio de una acción surge del encuentro entre quienes quieren comprar y quienes quieren vender.",r:"M4 · P10"},
{id:"M4-62",m:4,q:"¿Qué norma establece la obligación de presentar información contable periódica para emisoras de acciones?",o:["Normas CNV Título IV","Normas CNV Título XI","Normas CNV Título II, Cap. III","Ley 19.550, art. 188"],a:0,e:"El régimen informativo periódico de las emisoras está en el Título IV de las Normas CNV.",r:"M4 · P11"},
{id:"M4-63",m:4,q:"¿Qué indica un PER elevado en una acción?",o:["Que la empresa reparte dividendos altos en relación con su precio","Que la acción cotiza por debajo de su valor libro","Que el mercado espera alto crecimiento de beneficios","Que la empresa tiene un endeudamiento elevado"],a:2,e:"Si se paga muchas veces la ganancia actual es porque el mercado descuenta que los beneficios van a crecer.",r:"M4 · P12"},
{id:"M4-59",m:4,q:"¿Qué representa el modelo cost of carry en la valuación de futuros?",o:["La relación entre el precio spot y el precio futuro considerando los costos de financiación","El margen de garantía exigido por el mercado","La prima de la opción sobre el futuro","La diferencia entre precio de compra y de venta"],a:0,e:"Precio futuro = spot + costos de mantener la posición hasta el vencimiento.",r:"M4 · P13"},
{id:"M4-64",m:4,q:"¿Cuál es el principal objetivo de un contrato de futuros?",o:["Obtener financiamiento de largo plazo","Adquirir derechos políticos sobre el emisor","Garantizar un rendimiento fijo al inversor","La cobertura contra variaciones de precios"],a:3,e:"El futuro permite fijar hoy el precio de una operación futura y así cubrirse de las variaciones de precio.",r:"M4 · P14"},
{id:"M4-65",m:4,q:"¿Qué mide la volatilidad implícita en opciones?",o:["La expectativa del mercado sobre la variabilidad futura del precio","La variabilidad pasada del precio del subyacente en la última rueda","El valor intrínseco de la opción","La sensibilidad de la acción respecto del mercado"],a:0,e:"Es la volatilidad que el mercado está descontando en las primas: mira hacia adelante, no hacia atrás.",r:"M4 · P15"},
{id:"M4-66",m:4,q:"¿Cuál es la diferencia entre una opción call y una opción put?",o:["La call otorga derecho a vender y la put a comprar","La call otorga derecho a comprar y la put a vender","La call obliga a comprar y la put obliga a vender","La call se negocia en mercados autorizados y la put sólo fuera de ellos"],a:1,e:"Call = derecho de compra; put = derecho de venta. El que tiene la obligación es el lanzador.",r:"M4 · P16"},
{id:"M4-67",m:4,q:"¿Qué norma regula la operatoria de derivados en mercados autorizados por la CNV?",o:["Ley 23.576","Ley 24.083","Ley 19.550","Ley 26.831"],a:3,e:"La Ley 26.831 de Mercado de Capitales es la que alcanza a los mercados autorizados y su operatoria, incluidos los derivados.",r:"M4 · P17"},
{id:"M4-60",m:4,q:"¿Cuál es el principal riesgo al utilizar derivados para cobertura?",o:["Riesgo de crédito del mercado","Riesgo regulatorio","Riesgo de reinversión","Riesgo de base: la diferencia entre el activo cubierto y el activo del contrato"],a:3,e:"La cobertura no es perfecta cuando el subyacente del contrato no coincide exactamente con el activo a cubrir.",r:"M4 · P18"},
{id:"M4-19",m:4,q:"¿Cuál es el objetivo principal de las Normas Internacionales de Información Financiera (NIIF)?",o:["Uniformar la presentación de estados financieros a nivel global","Establecer las normas de auditoría aplicables","Fijar la política de dividendos de las emisoras","Determinar la base imponible del impuesto a las ganancias"],a:0,e:"Las NIIF buscan que los estados financieros se presenten igual en todo el mundo, para poder compararlos.",r:"M4 · P19"},
{id:"M4-22",m:4,q:"¿Cuál es la diferencia clave entre valor histórico y valor corriente en contabilidad?",o:["El valor corriente considera precios de mercado actuales","El valor histórico incluye el ajuste por inflación","El valor corriente sólo se aplica a los pasivos","No hay diferencia bajo NIIF"],a:0,e:"Histórico: costo de origen. Corriente: precios de mercado del momento de la medición.",r:"M4 · P20"},
{id:"M4-68",m:4,q:"¿Qué norma regula el nuevo informe extenso de auditoría en Argentina?",o:["Resolución Técnica N° 37","Ley 19.550","Resolución Técnica N° 26","Ley 26.831"],a:0,e:"La RT 37 de la FACPCE es la norma de auditoría que regula el nuevo informe extenso.",r:"M4 · P21"},
{id:"M4-69",m:4,q:"¿Cuál es el objetivo del nuevo informe extenso de auditoría?",o:["Reemplazar la opinión del auditor por un resumen detallado de todos los hallazgos del trabajo","Reducir la extensión del informe tradicional","Mejorar la transparencia sobre riesgos y juicios significativos","Certificar la solvencia futura de la entidad"],a:2,e:"El informe extenso cuenta más sobre los riesgos y los juicios significativos de la auditoría, para que el usuario entienda mejor.",r:"M4 · P22"},
{id:"M4-114",m:4,q:"¿Qué norma establece la obligación de presentar información contable periódica por emisoras?",o:["Ley 23.576, art. 10","Normas CNV Título VI","Normas CNV Título IV","Normas CNV Título XVIII"],a:2,e:"Igual que en la P11: el régimen informativo periódico de las emisoras está en el Título IV de las Normas CNV.",r:"M4 · P23"},
{id:"M4-70",m:4,q:"¿Cuál es un principio fundamental en la aplicación de NIIF?",o:["Presentar información financiera relevante y fiable","Valuar todos los activos a su costo histórico","Priorizar los estados individuales sobre los consolidados","Minimizar la carga impositiva de la entidad"],a:0,e:"La información tiene que servir para decidir (relevante) y poder creerse (fiable).",r:"M4 · P24"},
{id:"M4-41",m:4,q:"¿Qué sociedades están bajo control societario de la Comisión Nacional de Valores?",o:["Todas las sociedades anónimas del país","Sólo las emisoras de acciones","Las que hacen oferta pública de valores negociables","Las sociedades con más de 100 accionistas"],a:2,e:"El control societario de la CNV alcanza a las sociedades que hacen oferta pública de sus valores negociables, sean acciones u otros valores.",r:"M4 · P25"},
{id:"M4-71",m:4,q:"¿Qué órgano societario requiere publicidad mediante inscripción registral?",o:["La asamblea ordinaria","La comisión fiscalizadora","El comité de auditoría del directorio","La asamblea extraordinaria"],a:3,e:"Según la guía, es la asamblea extraordinaria: la que decide, entre otras cosas, las reformas de estatuto que luego se inscriben.",r:"M4 · P26"},
{id:"M4-72",m:4,q:"¿Qué norma regula el depósito de acciones para asistir a asambleas?",o:["Ley 23.576","Ley 26.831","Ley 19.550","Ley 22.169"],a:2,e:"El depósito de acciones para concurrir a la asamblea es un tema de la Ley General de Sociedades 19.550.",r:"M4 · P27"},
{id:"M4-115",m:4,q:"¿Qué plazo tienen las emisoras para presentar información contable periódica?",o:["30 días corridos","90 días corridos","60 días corridos","45 días hábiles"],a:2,e:"La guía responde 60 días corridos. Ojo: para esta pregunta la guía da 60 días corridos; en la P64 da 42 días (trimestrales) y 70 días (anuales).",r:"M4 · P28"},
{id:"M4-73",m:4,q:"¿Qué norma regula la inscripción y control de auditores externos?",o:["Normas CNV Título IV","Normas CNV Título XI","Normas CNV Título II, Cap. III","Ley 19.550"],a:2,e:"El Registro de Auditores Externos y su control están en el Título II, Capítulo III de las Normas CNV.",r:"M4 · P29"},
{id:"M4-74",m:4,q:"¿Qué requisito deben cumplir las sociedades bajo régimen de oferta pública respecto a sus estatutos?",o:["Deben inscribir reformas estatutarias en el registro público","Deben publicarlas sólo en su sitio web institucional y en la memoria del ejercicio siguiente","Deben someterlas a la aprobación del mercado donde listan sus acciones","Deben informarlas únicamente en la memoria anual"],a:0,e:"Toda reforma de estatuto se inscribe en el registro público.",r:"M4 · P30"},
{id:"M4-21",m:4,q:"¿Cómo se define a la moneda funcional?",o:["La moneda de curso legal del país donde la entidad está constituida","Es la moneda del entorno económico principal en el que opera la entidad","La moneda en que se presentan los estados financieros ante la CNV","La moneda en que se emitieron los valores negociables"],a:1,e:"Funcional es la del entorno económico principal donde opera la entidad; no es necesariamente la de curso legal ni la de presentación.",r:"M4 · P31"},
{id:"M4-17",m:4,q:"¿Cuántos estados contables tienen obligación de hacer públicos las empresas que hacen oferta pública de sus valores negociables durante el transcurso de un año calendario?",o:["Dos","Tres","Cuatro","Doce"],a:2,e:"Tres trimestrales más el anual: cuatro presentaciones al año.",r:"M4 · P32"},
{id:"M4-15",m:4,q:"El Activo es:",o:["El conjunto de bienes y derechos que posee una sociedad","El aporte de los accionistas","La diferencia entre ingresos y egresos del ejercicio","El conjunto de obligaciones frente a terceros"],a:0,e:"Bienes y derechos. Las obligaciones son el pasivo.",r:"M4 · P33"},
{id:"M4-28",m:4,q:"El auditor independiente emite su informe profesional con ABSTENCIÓN de opinión cuando:",o:["Existen desvíos poco significativos respecto de las normas contables","La entidad presenta pérdidas acumuladas","Detecta errores que la dirección corrigió antes de emitir su informe","No puede obtener evidencias adecuadas y suficientes en las que basar su opinión"],a:3,e:"Se abstiene porque no tiene con qué opinar: le falta evidencia adecuada y suficiente.",r:"M4 · P34"},
{id:"M4-75",m:4,q:"El auditor independiente emite su informe profesional con opinión ADVERSA cuando:",o:["La dirección no presentó la reseña informativa junto con los estados financieros","Existen desvíos no significativos respecto de las normas contables, que el auditor detalla en una nota","Los estados financieros no fueron preparados de acuerdo con las normas contables que resulten de aplicación","La entidad presenta pérdidas acumuladas que superan el capital social y las reservas del ejercicio anterior"],a:2,e:"Adversa: el auditor tiene evidencia y concluye que los EEFF no se ajustan al marco contable aplicable.",r:"M4 · P35"},
{id:"M4-29",m:4,q:"El auditor independiente emite su OPINIÓN profesional respecto de:",o:["Los estados financieros correspondientes al ejercicio anual (o de cierre de ejercicio)","Los estados financieros trimestrales","La memoria del directorio","El código de gobierno societario"],a:0,e:"La opinión del auditor se emite sobre los estados financieros anuales, los de cierre de ejercicio.",r:"M4 · P36"},
{id:"M4-76",m:4,q:"Con relación a los auditores externos, la Comisión Nacional de Valores:",o:["Sólo lleva el registro de auditores, sin facultades de supervisión sobre su trabajo","Sólo puede supervisarlos a pedido de la emisora","Cuenta con amplias facultades de supervisión","No tiene facultades: los controla únicamente el Consejo Profesional"],a:2,e:"La CNV no sólo registra a los auditores externos: los supervisa con amplias facultades.",r:"M4 · P37"},
{id:"M4-12",m:4,q:"El índice de inmovilización del capital relaciona:",o:["El activo corriente con el activo total","El activo no corriente con el total del activo","El pasivo no corriente con el patrimonio neto","Los bienes de uso con el capital social"],a:1,e:"Inmovilización = Activo no corriente / Activo total.",r:"M4 · P38"},
{id:"M4-09",m:4,q:"El índice de liquidez de una empresa indica:",o:["La proporción de los activos invertida en bienes de largo plazo","El grado de endeudamiento con terceros respecto del capital propio","La capacidad de la empresa de cancelar sus deudas de largo plazo con sus reservas","La capacidad de la empresa de cancelar sus obligaciones a corto plazo"],a:3,e:"La liquidez mira el corto plazo: si la empresa puede pagar lo que vence pronto.",r:"M4 · P39"},
{id:"M4-116",m:4,q:"El índice de liquidez de una empresa se obtiene:",o:["Relacionando el activo total con el pasivo total","Relacionando el activo corriente con el activo total","Relacionando el pasivo corriente con el patrimonio neto","Relacionando el activo corriente con el pasivo corriente"],a:3,e:"Liquidez = Activo corriente / Pasivo corriente: lo que se hace líquido en el año contra lo que vence en el año.",r:"M4 · P40"},
{id:"M4-11",m:4,q:"El índice de rentabilidad de la inversión de una empresa indica:",o:["La velocidad de rotación de los inventarios de la empresa","La proporción del resultado que se distribuye como dividendos","La tasa de retribución del capital aportado por sus propietarios","El margen de ganancia obtenido sobre las ventas del ejercicio"],a:2,e:"Mide cuánto rinde el capital que pusieron los dueños.",r:"M4 · P41"},
{id:"M4-117",m:4,q:"El índice de rentabilidad de la inversión se obtiene:",o:["Relacionando el resultado del ejercicio con el patrimonio neto","Relacionando el resultado del ejercicio con las ventas","Relacionando los dividendos pagados con el capital social","Relacionando el resultado del ejercicio con el pasivo total"],a:0,e:"Rentabilidad de la inversión = Resultado del ejercicio / Patrimonio neto.",r:"M4 · P42"},
{id:"M4-10",m:4,q:"El índice de solvencia se obtiene:",o:["Relacionando el activo total con el pasivo corriente","Relacionando el pasivo total con el activo corriente","Relacionando el patrimonio neto total con el pasivo total","Relacionando el activo no corriente con el patrimonio neto"],a:2,e:"Solvencia = PN / Pasivo total.",r:"M4 · P43"},
{id:"M4-30",m:4,q:"El “informe largo” o “KAM” (del inglés, Key Audit Matters) del auditor independiente tiene por objeto:",o:["Reemplazar al informe de auditoría tradicional por un resumen de hallazgos","Brindar mayor información a los inversores y otros usuarios de los estados financieros sobre cuestiones relevantes halladas en el curso de la auditoría","Certificar que no existen errores significativos en los estados financieros","Explicar las salvedades del auditor cuando su opinión no es favorable"],a:1,e:"Los KAM cuentan las cuestiones relevantes que el auditor encontró en la auditoría, para informar mejor a inversores y usuarios.",r:"M4 · P44"},
{id:"M4-118",m:4,q:"El “informe largo” o “KAM” (del inglés, Key Audit Matters) del auditor independiente será de emisión obligatoria cuando se refiera a:",o:["Estados financieros de cualquier entidad bajo control de la CNV","Estados financieros trimestrales de emisoras PyME CNV","Estados financieros con opinión adversa o abstención","Estados financieros de entidades listadas"],a:3,e:"El KAM es obligatorio cuando el informe es sobre estados financieros de entidades listadas.",r:"M4 · P45"},
{id:"M4-119",m:4,q:"El “informe largo” o “KAM” (del inglés, Key Audit Matters) del auditor independiente:",o:["Cuando existe incertidumbre material por empresa en funcionamiento, el asunto se comunica siempre como una KAM","Reemplaza la sección de opinión del informe del auditor","Cuando existe incertidumbre material por empresa en funcionamiento, el asunto se comunica en una sección separada del informe, no como KAM","Sólo se emite cuando el auditor se abstiene de opinar"],a:2,e:"La incertidumbre material sobre empresa en funcionamiento no se informa como KAM: va en una sección propia del informe.",r:"M4 · P46"},
{id:"M4-23",m:4,q:"El procedimiento de ajuste por inflación a los fines de exposición requiere que se presente:",o:["Sólo el ejercicio actual ajustado","Únicamente una nota explicativa","Ambos ejercicios a valores históricos","El ejercicio anterior ajustado y reexpresado y el ejercicio actual ajustado"],a:3,e:"Para que la comparación tenga sentido, ambos ejercicios deben expresarse en moneda homogénea.",r:"M4 · P47"},
{id:"M4-34",m:4,q:"El Registro de Auditores Externos y el Registro de Asociaciones de Profesionales Auditores son de acceso público a través del:",o:["Sitio web de la Comisión Nacional de Valores","Boletín Oficial, en su publicación anual","Sitio web de cada mercado autorizado","Registro Público de cada jurisdicción"],a:0,e:"Los dos registros se consultan públicamente en el sitio web de la CNV.",r:"M4 · P48"},
{id:"M4-37",m:4,q:"El sistema de gestión de calidad de una firma de auditoría debe proporcionarle una seguridad razonable de que ésta cumple con:",o:["La ausencia total de errores en los estados financieros auditados","La solvencia de la entidad auditada durante el ejercicio siguiente","Las normas profesionales y los requerimientos legales y reglamentarios aplicables, y el informe emitido por el auditor es adecuado en función de las circunstancias","Los plazos de presentación de la CNV para todas sus auditorías"],a:2,e:"El sistema de calidad busca asegurar que la firma cumpla las normas y que su informe sea el adecuado para el caso.",r:"M4 · P49"},
{id:"M4-14",m:4,q:"El valor libro de una acción es igual a:",o:["La cotización de cierre del último ejercicio","El patrimonio neto dividido la cantidad de acciones en circulación","El capital social dividido por la cantidad de acciones","El resultado del ejercicio dividido por la cantidad de acciones"],a:1,e:"Valor libro por acción = PN / acciones en circulación.",r:"M4 · P50"},
{id:"M4-120",m:4,q:"El valor libro del patrimonio neto es igual a los activos de la firma:",o:["Más sus pasivos","Menos el capital social","Menos sus pasivos","Menos sus pasivos corrientes"],a:2,e:"Es la ecuación patrimonial dada vuelta: PN = Activo − Pasivo.",r:"M4 · P51"},
{id:"M4-77",m:4,q:"Es causal de exclusión del Registro de Asociaciones de Profesionales Auditores que lleva la CNV:",o:["No haber presentado la memoria anual de sus actividades","Tener menos de cinco socios inscriptos","Cambiar su domicilio legal","El incumplimiento de las Normas de la Comisión Nacional de Valores"],a:3,e:"La causal de exclusión de la asociación es incumplir las Normas CNV.",r:"M4 · P52"},
{id:"M4-33",m:4,q:"Es causal de exclusión del Registro de Auditores Externos que lleva la CNV:",o:["Ser sancionado con inhabilitación por la CNV por aplicación del régimen de sanciones del artículo 132 de la Ley 26.831 (y mod.)","No presentar declaración jurada de bienes","Auditar más de tres emisoras simultáneamente","Tener menos de cinco años de matrícula"],a:0,e:"La inhabilitación que aplica la CNV bajo el art. 132 de la Ley 26.831 excluye al auditor del registro.",r:"M4 · P53"},
{id:"M4-121",m:4,q:"Están obligadas a inscribirse en el Registro de Asociaciones de Profesionales Auditores, las asociaciones profesionales cuyos socios:",o:["Estén matriculados en más de una jurisdicción del país","Certifiquen exclusivamente estados financieros de entidades financieras","Integren una red internacional de firmas de auditoría","Certifiquen estados financieros de cualquier entidad, patrimonio o sujeto que se encuentre bajo el control de la CNV"],a:3,e:"El criterio es el mismo que para los auditores: que sus socios certifiquen EEFF de sujetos bajo control de la CNV.",r:"M4 · P54"},
{id:"M4-32",m:4,q:"Están obligados a inscribirse en el Registro de Auditores Externos de la CNV, los contadores públicos que:",o:["Estén matriculados en cualquier consejo profesional del país","Sean socios de firmas internacionales","Auditen sólo a emisoras de acciones","Certifiquen estados financieros de cualquier entidad, patrimonio o sujeto que se encuentre bajo el control de la CNV"],a:3,e:"El criterio es certificar EEFF de sujetos bajo control de la CNV.",r:"M4 · P55"},
{id:"M4-78",m:4,q:"Están obligados a mantener un sistema de gestión de calidad de las auditorías externas las firmas de auditoría que:",o:["Certifican estados financieros de entidades autorizadas a hacer oferta pública, confeccionados bajo NIIF","Certifican estados financieros de cualquier sociedad del país, haga o no oferta pública de sus valores","Auditan exclusivamente entidades financieras reguladas por el BCRA, cualquiera sea el marco contable que utilicen","Forman parte de redes internacionales"],a:0,e:"El requisito alcanza a las firmas que certifican EEFF bajo NIIF de entidades con oferta pública.",r:"M4 · P56"},
{id:"M4-13",m:4,q:"La ecuación patrimonial básica está definida por la siguiente fórmula:",o:["Activo − Pasivo = Patrimonio Neto","Activo + Pasivo = Patrimonio Neto","Patrimonio Neto − Activo = Pasivo","Activo = Pasivo × Patrimonio Neto"],a:0,e:"A − P = PN: lo que queda para los dueños después de restar las deudas.",r:"M4 · P57"},
{id:"M4-79",m:4,q:"La reseña informativa es obligatoria:",o:["Sólo en los estados contables anuales","Sólo en los estados contables trimestrales","En los estados contables anuales y trimestrales","Sólo cuando la emisora hace oferta pública de acciones"],a:2,e:"Acompaña tanto a los anuales como a los trimestrales.",r:"M4 · P58"},
{id:"M4-20",m:4,q:"Las Normas Internacionales de Información Financiera (NIIF) de Contabilidad emanan:",o:["De la FACPCE","De la CNV","Del IASB","Del IAASB"],a:2,e:"Las NIIF las dicta el IASB (International Accounting Standards Board).",r:"M4 · P59"},
{id:"M4-80",m:4,q:"Las entidades financieras emisoras de acciones y/u obligaciones negociables pueden presentar sus estados financieros conforme a:",o:["Normas que dicta el BCRA","Normas que dicta la Inspección General de Justicia","Normas contables que elija su directorio","Normas que dicta la AFIP"],a:0,e:"Excepción a la regla NIIF: las entidades financieras presentan conforme a las normas del BCRA.",r:"M4 · P60"},
{id:"M4-122",m:4,q:"Las interpretaciones de las Normas Internacionales de Información Financiera (NIIF) de Contabilidad sólo pueden ser emanadas:",o:["Del IAASB","De la FACPCE","Del IFRIC","De la CNV"],a:2,e:"Las interpretaciones oficiales de las NIIF las emite sólo el IFRIC.",r:"M4 · P61"},
{id:"M4-81",m:4,q:"Las Normas Internacionales de Información Financiera (NIIF) de Contabilidad:",o:["Exigen que la moneda funcional sea siempre el dólar estadounidense","Distinguen entre moneda funcional y moneda de presentación","No distinguen: la moneda funcional es la de presentación","Imponen como moneda funcional la del país del domicilio legal de la entidad"],a:1,e:"Funcional: la del entorno económico principal. De presentación: la que se usa para exponer los EEFF.",r:"M4 · P62"},
{id:"M4-16",m:4,q:"Los estados contables básicos son:",o:["Balance, memoria, informe del síndico e informe del auditor","Balance general y anexos","Estado de resultados y reseña informativa","El estado de situación financiera, el estado de resultados integrales, el estado de cambios en el patrimonio y el estado de flujos de efectivo"],a:3,e:"Son los cuatro estados básicos: situación financiera, resultados integrales, cambios en el patrimonio y flujos de efectivo.",r:"M4 · P63"},
{id:"M4-18",m:4,q:"Los plazos de presentación de los estados financieros para emisoras de acciones y/u obligaciones negociables son:",o:["30 días corridos para trimestrales y 90 días corridos para anuales","42 días corridos para trimestrales y 70 días corridos para anuales","42 días hábiles para trimestrales y 70 días hábiles para anuales","45 días corridos para trimestrales y 120 días corridos para anuales"],a:1,e:"42 días corridos para los trimestrales y 70 corridos para los anuales. Ojo: para esta pregunta la guía da 42/70 días; en la P28 da 60 días corridos.",r:"M4 · P64"},
{id:"M4-27",m:4,q:"Para las Normas Internacionales de Información Financiera (NIIF) de Contabilidad tiene preeminencia la información contenida en los estados financieros:",o:["Consolidados","Individuales","Proyectados","Trimestrales"],a:0,e:"Para las NIIF prevalece la información de los estados consolidados.",r:"M4 · P65"},
{id:"M4-82",m:4,q:"Que los estados financieros estén confeccionados de acuerdo con las NIIF de Contabilidad implica:",o:["Que se aplicaron las NIIF que la emisora eligió","Que se aplicaron las NIIF salvo las de consolidación","Que están confeccionados de acuerdo con todas las NIIF vigentes","Que se aplicaron las NIIF sólo a los rubros significativos y las NCPA al resto de las partidas"],a:2,e:"No se puede decir que se aplican NIIF eligiendo algunas: el cumplimiento tiene que ser con todas las vigentes.",r:"M4 · P66"},
{id:"M4-83",m:4,q:"Se considera que el auditor externo cumple con el requisito de independencia cuando:",o:["No audita a más de tres emisoras bajo control de la CNV y rota de socio firmante cada cinco ejercicios","Fue designado por el directorio de la emisora y su nombramiento fue informado a la CNV dentro de los plazos previstos","Su desempeño y conducta profesional le permiten emitir una opinión íntegra, veraz y objetiva con relación a las evidencias examinadas","Sus honorarios no superan el arancel de referencia"],a:2,e:"La independencia se mide por la capacidad de opinar en forma íntegra, veraz y objetiva sobre la evidencia.",r:"M4 · P67"},
{id:"M4-26",m:4,q:"Según el Régimen Informativo Periódico, los estados financieros se pueden confeccionar en base a Normas Contables Profesionales Argentinas (NCPA) si:",o:["Pertenecen a emisoras del régimen general que lo decidan por asamblea","Pertenecen a emisoras de acciones y/u obligaciones negociables que califican como PyME CNV","Pertenecen a sociedades extranjeras que listan en el país","Pertenecen a emisoras cuyo auditor externo lo autorice"],a:1,e:"La PyME CNV puede usar NCPA; el resto del régimen general va con NIIF.",r:"M4 · P68"},
{id:"M4-84",m:4,q:"Según las NIIF de Contabilidad, el Estado de Resultados Integrales puede tener una segunda parte denominada:",o:["Resultados No Asignados","Reserva de Revalúo","Resultados Extraordinarios del Ejercicio","Otros Resultados Integrales"],a:3,e:"Es la sección de Otros Resultados Integrales (ORI).",r:"M4 · P69"},
{id:"M4-85",m:4,q:"Si los estados financieros están confeccionados con moneda funcional distinta al peso, en Argentina:",o:["La moneda de presentación será pesos","La moneda de presentación será la moneda funcional","La emisora elige libremente la moneda de presentación","Se presentan en dólares estadounidenses"],a:0,e:"La moneda funcional puede ser otra, pero la de presentación en Argentina es el peso.",r:"M4 · P70"},
{id:"M4-35",m:4,q:"Solo pueden desempeñarse como auditores externos, los profesionales designados por:",o:["El directorio de la emisora","La CNV, de una lista de sorteo","El comité de auditoría","La Asamblea General de Accionistas del emisor de los estados financieros"],a:3,e:"La designación es competencia de la asamblea, no del directorio.",r:"M4 · P71"},
{id:"M4-86",m:4,q:"Tanto en el régimen informativo anual como trimestral:",o:["Es obligatoria la presentación del Informe del Auditor Externo","El informe del auditor externo es optativo","Sólo es obligatorio el informe de la comisión fiscalizadora","El informe del auditor externo se exige sólo en el régimen informativo anual"],a:0,e:"En los dos regímenes, anual y trimestral, el informe del auditor externo es obligatorio.",r:"M4 · P72"},
{id:"M4-25",m:4,q:"Una emisora que se encuentra en el régimen general de oferta pública presenta sus estados financieros a la CNV, confeccionados conforme a:",o:["Normas contables de la Inspección General de Justicia","US GAAP (normas contables de los Estados Unidos)","Normas Internacionales de Información Financiera (NIIF) de Contabilidad","Las normas que elija su directorio"],a:2,e:"En el régimen general la regla es NIIF; las demás normas son excepciones para casos puntuales.",r:"M4 · P73"},
{id:"M4-87",m:4,q:"Es causal de cancelación de la inscripción de un auditor externo en el Registro de Auditores Externos que el auditor no haya sido designado, como titular o suplente, auditor de los estados financieros de un sujeto bajo control de la CNV durante los últimos:",o:["UN (1) año","DOS (2) años","TRES (3) años","CINCO (5) años"],a:2,e:"Tres años sin designación como auditor de un sujeto bajo control de la CNV: se cancela la inscripción.",r:"M4 · P74"},
{id:"M4-88",m:4,q:"La función de supervisión del control de calidad de las auditorías externas que ejerce la CNV resulta:",o:["De la Ley 19.550 de Sociedades Comerciales","De la Ley 22.169","De la Ley 26.831 (y su modificatoria Ley 27.440)","De la Resolución Técnica N° 37"],a:2,e:"Esa facultad de la CNV surge de la Ley de Mercado de Capitales 26.831, modificada por la 27.440.",r:"M4 · P75"},
{id:"M4-38",m:4,q:"Las Normas Internacionales de Auditoría (NIA) son de:",o:["Aplicación optativa, a elección del auditor","Aplicación obligatoria para estados financieros confeccionados bajo cualquier marco de información, conforme RT 37","Aplicación sólo para entidades listadas","Aplicación sólo para estados financieros bajo NIIF"],a:1,e:"Según la RT 37, las NIA son obligatorias cualquiera sea el marco contable utilizado.",r:"M4 · P76"},
{id:"M4-89",m:4,q:"Los requisitos de independencia son aplicables:",o:["Sólo al auditor externo que firma el informe","Sólo a los socios de la firma de auditoría, cualquiera sea su participación en el trabajo sobre el ente auditado","Sólo al auditor firmante y a los socios de la firma, pero no al resto del equipo de trabajo","Tanto al auditor externo como a los integrantes del equipo de trabajo que interviene en las tareas de auditoría"],a:3,e:"La independencia no es sólo del que firma: alcanza a todo el equipo que participa del trabajo.",r:"M4 · P77"},
{id:"M4-36",m:4,q:"Se considera que el auditor externo no cumple con el requisito de independencia:",o:["Si audita a la misma entidad por más de tres ejercicios","Si percibe honorarios por encima del arancel de referencia","Si integra una asociación de profesionales","Si es propietario, director, gerente o administrador del ente cuyos estados financieros certifica"],a:3,e:"Nadie puede auditar con independencia lo que él mismo es dueño o administra.",r:"M4 · P78"},
{id:"M4-90",m:4,q:"La documentación del trabajo del auditor externo tiene por finalidad:",o:["Registrar los procedimientos y juicios que fundamentan su informe y evidenciar el cumplimiento de las normas y los requerimientos legales y reglamentarios aplicables","Reemplazar los estados financieros en caso de extravío","Servir de base para el cálculo de sus honorarios y para la facturación de las horas insumidas por el equipo","Informar a los accionistas sobre la gestión del directorio"],a:0,e:"Los papeles de trabajo respaldan el informe y demuestran que se cumplieron las normas.",r:"M4 · P79"},
{id:"M4-91",m:4,q:"El auditor externo debe mantener permanentemente una actitud y conducta profesional acorde con:",o:["Principios de ética e independencia","Las instrucciones del directorio de la emisora","Los intereses del accionista controlante","Las políticas comerciales de su firma"],a:0,e:"Ética e independencia son la base de la conducta del auditor.",r:"M4 · P80"},
{id:"M4-92",m:4,q:"Para realizar una tarea de auditoría sin prejuicios, libre de conflicto de intereses o de influencia indebida de terceros, el auditor debe:",o:["Obtener autorización previa de la CNV","Limitarse a revisar lo que le presenta la dirección y aceptar sus explicaciones sin pedir respaldo","Mantener una actitud mental independiente e independencia aparente","Rotar de cliente cada ejercicio"],a:2,e:"Se exigen las dos: ser independiente (actitud mental) y parecerlo ante terceros (independencia aparente).",r:"M4 · P81"},
{id:"M4-93",m:4,q:"En el curso de una auditoría, el profesional puede:",o:["Aplicar procedimientos analíticos para obtener evidencias válidas y suficientes","Modificar los estados financieros de la entidad","Delegar su opinión en la comisión fiscalizadora cuando no obtenga evidencias suficientes","Omitir la documentación de su trabajo"],a:0,e:"Los procedimientos analíticos son una de las herramientas válidas para reunir evidencia.",r:"M4 · P82"},
{id:"M4-39",m:4,q:"Una certificación emitida por un profesional contable es:",o:["Un informe de constatación","Una opinión de auditoría abreviada","Una revisión limitada","Un dictamen con salvedades"],a:0,e:"La certificación constata hechos comprobables; no expresa opinión sobre estados financieros en su conjunto.",r:"M4 · P83"},
{id:"M4-24",m:4,q:"Si en una nueva NIIF o modificación de una ya existente, el IASB permite la aplicación anticipada de la norma:",o:["Puede aplicarse anticipadamente sin restricciones en el mercado de capitales","Puede aplicarse anticipadamente con autorización del auditor externo","No puede aplicarse en forma anticipada en el mercado de capitales, según las Normas CNV","Debe aplicarse obligatoriamente en forma anticipada por todas las emisoras"],a:2,e:"Aunque el IASB lo permita, en el mercado de capitales, según las Normas CNV, la aplicación anticipada no rige. Ojo: en la P126 la guía agrega la excepción: salvo que, al adoptarse la norma, se la admita expresamente.",r:"M4 · P84"},
{id:"M4-94",m:4,q:"Si una compañía de seguros es autorizada a efectuar oferta pública de sus valores negociables:",o:["Debe aplicar los plazos generales de presentación de la CNV, sin excepción","Puede aplicar las normas y los plazos de presentación de información contable de la Superintendencia de Seguros de la Nación (SSN)","Debe presentar conforme a las normas de la Inspección General de Justicia","Queda eximida de presentar información contable ante la CNV"],a:1,e:"Excepción a la regla general: las aseguradoras pueden seguir las normas y plazos de la SSN.",r:"M4 · P85"},
{id:"M4-40",m:4,q:"Según el orden de absorción de pérdidas del Art. 11 del Capítulo III del Título IV de las Normas (N.T. 2013 y mod.):",o:["Se utiliza primero el capital social","Se utilizan primero los aportes irrevocables","Se utiliza primero la prima de emisión","Se utilizan primero las Ganancias Reservadas (voluntarias, estatutarias, especiales y legal, en ese orden)"],a:3,e:"Se agotan las ganancias reservadas, en ese orden, antes de tocar otros rubros del patrimonio.",r:"M4 · P86"},
{id:"M4-95",m:4,q:"Pueden las asociaciones mutuales presentar ante la CNV sus estados contables:",o:["De acuerdo con las normas de la Inspección General de Justicia","De acuerdo con las normas de la AFIP","De acuerdo con las normas del INAES","De acuerdo con las normas que fije su consejo directivo"],a:2,e:"Las mutuales presentan conforme a las normas del INAES.",r:"M4 · P87"},
{id:"M4-96",m:4,q:"La Comisión Nacional de Valores, bajo la órbita de su competencia, ejerce el control societario respecto de:",o:["Personas jurídicas privadas","Personas jurídicas públicas","Personas humanas que invierten en el mercado","Todos los organismos del Estado nacional"],a:0,e:"El control societario de la CNV recae sobre personas jurídicas privadas.",r:"M4 · P88"},
{id:"M4-123",m:4,q:"Las siguientes personas jurídicas se encuentran bajo control societario de la Comisión Nacional de Valores:",o:["Todas las entidades encuadradas en la Ley Nº 22.169, excluidas las PyME CNV Garantizadas","Todas las entidades encuadradas en la Ley Nº 22.169, incluidas las PyME CNV Garantizadas","Todas las sociedades anónimas inscriptas en el Registro Público","Sólo las entidades financieras autorizadas por el BCRA"],a:0,e:"Entran todas las de la Ley 22.169, con una excepción que conviene recordar: las PyME CNV Garantizadas quedan afuera.",r:"M4 · P89"},
{id:"M4-97",m:4,q:"Cuando una sociedad realiza una emisión de obligaciones negociables con oferta pública, debe:",o:["Publicar el aviso de emisión sólo en el Boletín Oficial","Publicar el aviso de emisión en un diario de mayor circulación durante tres días","Pedir autorización al Registro Público antes de publicar el aviso","Publicar el aviso de emisión en la Autopista de la Información Financiera"],a:3,e:"El aviso de emisión de ON con oferta pública va en la Autopista de la Información Financiera (AIF) de la CNV.",r:"M4 · P90"},
{id:"M4-124",m:4,q:"Las personas jurídicas sujetas a control societario de la Comisión Nacional de Valores deben solicitar la inscripción registral de:",o:["Los accionistas minoritarios","Los empleados jerárquicos","Los miembros del Directorio","Los asesores legales externos"],a:2,e:"Lo que se inscribe es la integración del Directorio: quiénes son sus miembros.",r:"M4 · P91"},
{id:"M4-98",m:4,q:"Si una persona jurídica sujeta a control societario de la CNV quiere cambiar su denominación social, deberá:",o:["Reformar su estatuto, con conformidad de la CNV e inscripción en el Registro Público","Comunicarlo por hecho relevante, sin reformar el estatuto","Obtener sólo la aprobación del directorio","Publicarlo en el Boletín Oficial y comunicarlo a la CNV, sin necesidad de reformar el estatuto ni inscribir nada"],a:0,e:"La denominación está en el estatuto: cambiarla es una reforma que necesita conformidad de la CNV e inscripción.",r:"M4 · P92"},
{id:"M4-99",m:4,q:"Para saber qué actividades tiene permitido desarrollar una sociedad emisora, debo revisar:",o:["La última memoria del directorio","El registro de acciones","El estatuto social","El prospecto de la última emisión"],a:2,e:"Las actividades permitidas surgen del objeto social, que está en el estatuto.",r:"M4 · P93"},
{id:"M4-125",m:4,q:"El registro de acciones de una sociedad emisora está a cargo de:",o:["Exclusivamente la CNV","El Registro Público de su jurisdicción","La propia emisora, bancos o Caja de Valores","El mercado donde listan sus acciones"],a:2,e:"El registro lo puede llevar la propia emisora o delegarse en un banco o en Caja de Valores.",r:"M4 · P94"},
{id:"M4-100",m:4,q:"Para saber cuál es el capital social de una sociedad emisora, debo revisar:",o:["El estatuto social y los estados contables","El registro de auditores externos","La memoria del directorio","Los hechos relevantes publicados en la Autopista de la Información Financiera"],a:0,e:"El capital figura en el estatuto y su evolución se ve en los estados contables.",r:"M4 · P95"},
{id:"M4-101",m:4,q:"Si necesito cursar una notificación a la sociedad emisora, para que la misma sea válida y vinculante, debo hacerlo a:",o:["El domicilio de cualquiera de sus directores","La sede social inscripta","La sucursal más cercana","El domicilio del agente colocador"],a:1,e:"La sede social inscripta es donde la sociedad recibe válidamente las notificaciones.",r:"M4 · P96"},
{id:"M4-102",m:4,q:"Si un accionista desea participar en una asamblea, debe comunicar su intención de asistir y depositar sus acciones ante:",o:["La CNV","El mercado donde listan las acciones","El agente de liquidación y compensación","La sociedad emisora"],a:3,e:"La comunicación y el depósito se hacen ante la propia sociedad emisora.",r:"M4 · P97"},
{id:"M4-126",m:4,q:"Si el directorio de una sociedad anónima admitida al régimen de oferta pública decide convocar a una asamblea de accionistas a celebrarse a distancia, deberá:",o:["Obtener autorización previa del mercado donde listan sus acciones","Decidirlo por mayoría simple del directorio, sin otro recaudo","Pedir autorización previa al Registro Público","Tenerlo previsto en el estatuto social"],a:3,e:"La asamblea a distancia no la habilita el directorio por su cuenta: tiene que estar prevista en el estatuto.",r:"M4 · P98"},
{id:"M4-112",m:4,q:"Cuando se produce la designación o cesación de directores en una persona jurídica bajo control societario de la CNV, se debe:",o:["Publicar un aviso en el Boletín Oficial e iniciar el trámite de inscripción en la CNV","Comunicarlo al mercado donde lista y esperar su conformidad","Inscribirlo sólo en el libro de actas del directorio","Pedir la aprobación previa de la Comisión Fiscalizadora"],a:0,e:"Doble paso: aviso en el Boletín Oficial y trámite de inscripción ante la CNV.",r:"M4 · P99"},
{id:"M4-42",m:4,q:"Las reformas de estatutos sociales de sociedades anónimas bajo control societario de la CNV deben ser aprobadas por:",o:["El directorio","La asamblea ordinaria","La asamblea extraordinaria","La comisión fiscalizadora"],a:2,e:"Reformar el estatuto es materia de la asamblea extraordinaria.",r:"M4 · P100"},
{id:"M4-43",m:4,q:"En una sociedad anónima bajo control societario de la CNV, el objeto social debe ser:",o:["Amplio y genérico","Revisado anualmente por la asamblea","Idéntico al de su controlante","Preciso y determinado"],a:3,e:"El objeto tiene que ser preciso y determinado: se tiene que saber qué hace la sociedad.",r:"M4 · P101"},
{id:"M4-44",m:4,q:"Las sociedades que se encuentran en el régimen de oferta pública de acciones, en caso de aumento de su capital social, deben:",o:["Obtener autorización de oferta pública de acciones de la CNV y la inscripción del aumento de capital en el Registro Público","Sólo inscribir el aumento en el Registro Público","Comunicarlo por AIF dentro de los 10 días","Convocar únicamente a asamblea ordinaria"],a:0,e:"Doble recaudo: autorización de oferta pública + inscripción registral.",r:"M4 · P102"},
{id:"M4-45",m:4,q:"¿Cuál de las siguientes características NO es propia de un bono cupón cero?",o:["No paga cupones de renta durante su vida","Se emite bajo la par","Un bono cupón cero puede negociarse sobre la par cuando bajan las tasas de interés","Su rendimiento surge de la diferencia entre precio y valor de rescate"],a:2,e:"El cupón cero cotiza siempre bajo la par: su precio es el valor descontado del único pago final.",r:"M4 · P103"},
{id:"M4-103",m:4,q:"El bono A paga amortización e interés semestralmente; el bono B paga interés semestral pero es bullet. Tienen el mismo cupón semestral, el mismo calendario de pagos y vencen en un año. Si ambos son descontados a una misma tasa:",o:["El valor actual de los flujos de A es mayor al de B","El valor actual de los flujos de B es mayor al de A","Ambos tienen el mismo valor actual","No se puede comparar sin conocer la tasa de descuento utilizada"],a:0,e:"A devuelve parte del capital a los 6 meses: un flujo que llega antes se descuenta menos y suma más valor actual.",r:"M4 · P104"},
{id:"M4-52",m:4,q:"¿Cuál de las siguientes situaciones puede provocar un incremento del ROE de una Sociedad?",o:["Que la ganancia neta disminuya 5% y el promedio del valor libro de las acciones disminuya 10%","Que la ganancia neta aumente 5% y el patrimonio neto aumente 10%","Que la ganancia neta y el patrimonio neto aumenten en la misma proporción","Que el pasivo se cancele con nuevos aportes"],a:0,e:"El denominador cae más que el numerador, entonces el cociente sube.",r:"M4 · P105"},
{id:"M4-51",m:4,q:"Los EEFF de EMISORA S.A. al 31/12/2024 muestran AC 11.492, ANC 26.973, PC 16.914, PNC 3.941 y PN 17.610 (en millones de $). El ratio de liquidez y el de endeudamiento son:",o:["68% y 1,18","65% y 0,96","145% y 1,18","68% y 2,18"],a:0,e:"Liquidez = 11.492/16.914 = 68%. Endeudamiento = (16.914+3.941)/17.610 = 1,18.",r:"M4 · P106"},
{id:"M4-53",m:4,q:"El 1° de octubre de 2024 Juan vendió 3 contratos en ROFEX de futuro dólar a diciembre de 2024 a $1010. El 1 de noviembre el contrato se ubica en $1009,50. ¿Cuál sería la ganancia o pérdida si cierra su posición? (Sin considerar costos de transacción)",o:["Una pérdida de $1.500","Una ganancia de $500","Una ganancia de $1.500","Sin resultado hasta el vencimiento"],a:2,e:"Vendido: gana si el precio baja. $0,50 × 3 contratos × US$1.000 = $1.500 de ganancia.",r:"M4 · P107"},
{id:"M4-104",m:4,q:"Tiene una posición de un contrato de futuro de soja por 30 toneladas, comprado inicialmente a 280 dólares la tonelada. Si el precio baja 10 dólares:",o:["Tiene diferencias a favor y cobra diferencias diarias","No hay efecto hasta el vencimiento del contrato","Tiene diferencias en contra y debe pagar diferencias diarias","No paga diferencias diarias: la pérdida se liquida recién al vencimiento del contrato"],a:2,e:"Comprado y el precio baja: pierde US$10 × 30 t = US$300, que se pagan como diferencias diarias.",r:"M4 · P108"},
{id:"M4-54",m:4,q:"Si la volatilidad de una acción baja, lo más probable que ocurra es:",o:["El precio de la call suba y el de la put baje","El precio tanto de una opción call como put disminuirá","Sólo se modifique el valor intrínseco","Las primas no se vean afectadas"],a:1,e:"La volatilidad alimenta el valor tiempo: si baja, bajan ambas primas.",r:"M4 · P109"},
{id:"M4-56",m:4,q:"¿Un split de acciones tiene efectos en el cálculo del índice ponderado por precio y/o el índice ponderado por capitalización bursátil?",o:["Afecta a ambos","No afecta a ninguno","Sólo afecta al ponderado por capitalización","Sólo afecta al índice ponderado por precio"],a:3,e:"El split cambia el precio unitario pero no la capitalización total.",r:"M4 · P110"},
{id:"M4-105",m:4,q:"Si un inversionista lanza una opción de venta sobre una acción, ¿qué pasará si el precio de mercado en la fecha de vencimiento de la opción excede el precio de ejercicio?",o:["El tenedor ejercerá la opción","El lanzador deberá comprar la acción al precio de ejercicio","El tenedor no ejercerá su opción","El lanzador deberá devolver la prima"],a:2,e:"Nadie vende al precio de ejercicio si en el mercado le pagan más: la put vence sin ejercerse y el lanzador se queda con la prima.",r:"M4 · P111"},
{id:"M4-127",m:4,q:"Si usted es un inversor y decide comprar un futuro de dólar, usted debe:",o:["Pagar una prima al vendedor del futuro","Integrar el valor total del contrato al momento de la compra","Poner una garantía inicial cuando compra el futuro","Pagar las diferencias recién al vencimiento del contrato"],a:2,e:"Al abrir la posición se integra una garantía inicial; el futuro no tiene prima ni se paga entero por adelantado.",r:"M4 · P112"},
{id:"M4-106",m:4,q:"Si usted compra un futuro de dólar con vencimiento dentro de un mes y vende un futuro de dólar con vencimiento en 3 meses, ¿cómo supone que será el margen a integrar por las posiciones?",o:["Sólo el de la posición comprada","Nulo, porque las posiciones se compensan totalmente","La suma completa de ambos márgenes, sin ninguna bonificación por compensar","Se integrarán ambos márgenes, pero recibirá una bonificación por compensación de riesgos"],a:3,e:"Se integran los dos márgenes, pero como las posiciones se compensan en parte, el mercado bonifica.",r:"M4 · P113"},
{id:"M4-128",m:4,q:"Usted es Gerente de Finanzas de una compañía manufacturera importadora de electrodomésticos. Hoy acuerda la compra de insumos por u$s 1.000.000, que abonará el día que reciba los productos, dentro de 60 días. Su equipo de research considera que las expectativas devaluatorias son mayores que lo estimado por el mercado. Usted debería:",o:["Comprar futuro de dólar a 60 días","Vender futuro de dólar a 60 días","Comprar una opción de venta sobre el dólar a 60 días","No cubrirse y comprar los dólares al contado el día del pago"],a:0,e:"Tiene que pagar dólares en 60 días y espera que suban más de lo que descuenta el mercado: comprando el futuro fija hoy el tipo de cambio.",r:"M4 · P114"},
{id:"M4-129",m:4,q:"Un inversionista compra una acción a $40 y una opción de venta sobre esa acción pagando una prima de $4, con un precio de ejercicio de $45. ¿Cuál será el valor de su inversión en la fecha de ejercicio final si el precio de la acción es $38? (Ignorar los costos de transacción)",o:["El resultado de esta operación es de $2 de pérdida","El resultado de esta operación es de $6 de pérdida","El resultado de esta operación es de $3 de ganancia","El resultado de esta operación es de $4 de pérdida"],a:3,e:"Es la respuesta que da la guía, y el examen corrige con la guía: marcá $4 de pérdida. Ojo que la cuenta directa da otra cosa (ejercés la put y vendés a $45 lo que te costó $40 + $4 de prima: +$1), pero para el examen vale la de la guía.",r:"M4 · P115"},
{id:"M4-47",m:4,q:"Un bono de cupón cero cotiza con un rendimiento del 9,6% y un valor nominal de $1.000. Si el bono vence en 10 años, ¿cuál sería el precio actual del bono? (utilice dos decimales)",o:["399,85","519,20","614,50","904,00"],a:0,e:"1.000 / (1,096)^10 ≈ 399,85. Es la lógica del descuento: a mayor tasa y mayor plazo, menor precio.",r:"M4 · P116"},
{id:"M4-130",m:4,q:"Una orden de divulgación parcial o ICEBERG es una orden parcialmente oculta porque:",o:["No se muestra su precio pero sí toda su cantidad","Se oculta la identidad del agente que la ingresa","Se muestra su precio y parcialmente su cantidad","Sólo se muestra en pantalla cuando se ejecuta al cierre"],a:2,e:"En la iceberg el precio está a la vista y la cantidad asoma sólo en parte, como la punta del témpano.",r:"M4 · P117"},
{id:"M4-48",m:4,q:"Un bono que paga cupones anuales tiene un valor nominal de $1.000, vence en 4 años, paga un cupón de $100 y tiene una TIR del 12%. El rendimiento actual o Current Yield de este bono es:",o:["10,00%","10,65%","12,00%","8,90%"],a:1,e:"CY = cupón / precio. El precio con TIR 12% es ≈ $939,25 → 100/939,25 = 10,65%.",r:"M4 · P118"},
{id:"M4-46",m:4,q:"Un bono sobre la par es negociado cuando:",o:["El precio es mayor que su valor nominal","La TIR es mayor que la tasa del cupón","El precio es menor que su valor nominal","El current yield iguala a la TIR"],a:0,e:"Sobre la par: el precio supera al valor nominal.",r:"M4 · P119"},
{id:"M4-49",m:4,q:"Una cartera tiene un bono X, un bono Y y un bono Z. Los precios son $1.050, $1.000 y $950 y sus durations 8, 6 y 4 respectivamente. ¿Cuál es la duration total de la cartera?",o:["6,00","6,07","6,50","5,80"],a:1,e:"Promedio ponderado por valor: (1050×8 + 1000×6 + 950×4) / 3.000 = 6,07.",r:"M4 · P120"},
{id:"M4-107",m:4,q:"Un inversor compra por 2 pesos una opción de compra de EMISORA S.A. con un precio de ejercicio de $40 y a su vez vende por 1 peso una opción de compra con un precio de ejercicio de $45. Si cuando vencen las opciones la acción cotiza $48, el inversionista tuvo como resultado:",o:["Una ganancia de $4","Una ganancia de $5","Una ganancia de $7","Una ganancia de $6, sin contar la call vendida"],a:0,e:"Call comprada: 48 − 40 − 2 = 6. Call vendida: −(48 − 45) + 1 = −2. Neto: $4 de ganancia.",r:"M4 · P121"},
{id:"M4-55",m:4,q:"Si el beta de una acción aumenta, es probable que su volatilidad:",o:["Haya incrementado respecto a la del mercado","Haya disminuido respecto del mercado","Se mantenga constante","No tenga relación con el beta"],a:0,e:"El beta mide la sensibilidad respecto del mercado: beta mayor, mayor volatilidad relativa.",r:"M4 · P122"},
{id:"M4-57",m:4,q:"La definición de venta en corto se corresponde con la siguiente afirmación:",o:["La venta de valores propios con liquidación diferida","La venta de futuros sin garantía inicial","Son aquellas operaciones de venta concertadas en el plazo de contado normal y cuya liquidación es realizada con valores negociables obtenidos en préstamo en la misma sesión de negociación","La venta de opciones lanzadas en descubierto"],a:2,e:"Se vende lo que no se tiene, tomándolo en préstamo en la misma rueda.",r:"M4 · P123"},
{id:"M4-58",m:4,q:"Respecto a las siguientes afirmaciones, señale cuál es verdadera:",o:["En una posición larga las potenciales ganancias son ilimitadas y las pérdidas pueden alcanzar el 100%; en una posición corta las ganancias están limitadas al 100% y las pérdidas son ilimitadas","En ambas posiciones las pérdidas están limitadas al capital invertido","En la posición corta las ganancias son ilimitadas","En la posición larga las pérdidas son ilimitadas"],a:0,e:"El precio puede subir sin techo (mata al vendido) pero no puede bajar de cero (limita al comprado).",r:"M4 · P124"},
{id:"M4-50",m:4,q:"Dada una duración modificada de 5,21 y su convexidad de 52,1, ¿cuál de las siguientes variaciones de precios de un bono es la correcta ante un incremento de la tasa de interés del 1,21%?",o:["−6,30%","−5,54%","−4,80%","+5,54%"],a:1,e:"Duration: −5,21 × 1,21% = −6,30%. Convexidad (la guía no usa el ½): 52,1 × (0,0121)² = +0,76%. Total: −5,54%.",r:"M4 · P125"},
{id:"M4-131",m:4,q:"La CNV restringe la aplicación anticipada de NIIF y NCPA por el principio de comparabilidad. Esta regla:",o:["Rige sólo para las NCPA; las NIIF pueden aplicarse anticipadamente","Rige salvo que el auditor externo apruebe la aplicación anticipada","Rige salvo que, al adoptarse la norma, se admita expresamente la aplicación anticipada","Rige sólo para las emisoras PyME CNV"],a:2,e:"La restricción tiene una salida: que la propia norma, al adoptarse, admita expresamente la aplicación anticipada. Ojo: en la P84 la guía contesta la regla general, sin la excepción.",r:"M4 · P126"},
{id:"M4-132",m:4,q:"Una emisora PyME CNV puede presentar estados bajo:",o:["NIIF únicamente, como el resto del régimen general","US GAAP, si lo aprueba su asamblea","Las normas que fije su auditor externo","NCPA, quedando excluida de la obligación de NIIF"],a:3,e:"La PyME CNV puede usar Normas Contables Profesionales Argentinas y no está obligada a aplicar NIIF.",r:"M4 · P127"},
{id:"M4-108",m:4,q:"Las entidades financieras registradas como emisoras ante la CNV pueden compatibilizar normas y plazos con el BCRA por:",o:["RG 1051/2025","Resolución Técnica N° 37","RG 936/2022","Ley 22.169"],a:2,e:"La RG 936/2022 permite a las entidades financieras compatibilizar normas y plazos con el BCRA.",r:"M4 · P128"},
{id:"M4-133",m:4,q:"Las compañías de seguros emisoras pueden compatibilizar normas y plazos con la SSN por:",o:["Ley 26.831, art. 19","RG 936/2022","Ley 19.550, art. 238","RG 1051/2025"],a:1,e:"La misma RG 936/2022 que alcanza a las financieras con el BCRA les permite a las aseguradoras compatibilizar con la SSN.",r:"M4 · P129"},
{id:"M4-109",m:4,q:"Para obligaciones negociables de bajo impacto, desde 2025 la CNV incorporó:",o:["La obligación de contar con dos calificaciones de riesgo","Un régimen de autorización previa caso por caso con dictamen de un agente de calificación de riesgo","La prohibición de colocarlas entre inversores no calificados","Un régimen de autorización automática con requisitos y tope en UVA"],a:3,e:"Bajo impacto = autorización automática, siempre que se cumplan los requisitos y no se supere el tope en UVA.",r:"M4 · P130"},
{id:"M4-110",m:4,q:"RG 1051/2025: en fideicomisos financieros, 2025 incorporó:",o:["Un régimen de oferta pública automática en supuestos definidos","La eliminación del fiduciario profesional","La obligación de listar en al menos dos mercados","Un régimen de colocación exclusiva entre inversores calificados"],a:0,e:"La RG 1051/2025 sumó la oferta pública automática para fideicomisos financieros en los supuestos que define.",r:"M4 · P131"},
{id:"M4-134",m:4,q:"En asambleas a distancia, para emisoras bajo control societario de la CNV se requiere:",o:["Previsión estatutaria","Autorización previa del mercado donde listan","Resolución del directorio por mayoría simple","Conformidad previa del Registro Público"],a:0,e:"Igual que en la P98: para hacer la asamblea a distancia tiene que estar previsto en el estatuto.",r:"M4 · P132"},
{id:"M4-135",m:4,q:"El aviso de emisión de ON con oferta pública debe publicarse en:",o:["Autopista de la Información Financiera","Un diario de mayor circulación nacional","El sitio web del mercado donde se lista","El Boletín Oficial, exclusivamente"],a:0,e:"El aviso de emisión va en la AIF, la Autopista de la Información Financiera de la CNV.",r:"M4 · P133"},
{id:"M4-136",m:4,q:"En KAM (NIA 701), ¿qué entidad está alcanzada obligatoriamente?",o:["Entidad financiera regulada por el BCRA","Emisora PyME CNV Garantizada","Entidad listada","Toda entidad que presente estados bajo NCPA"],a:2,e:"La NIA 701 hace obligatorio el KAM para las entidades listadas.",r:"M4 · P134"},
{id:"M4-31",m:4,q:"Going Concern: cuando existe incertidumbre material, el auditor debe:",o:["Comunicarlo como una cuestión clave de auditoría (KAM)","Abstenerse de opinar","Incluir una sección específica “Material Uncertainty Related to Going Concern” o “Going Concern”, separada de KAM","Omitirlo si la dirección presentó un plan de acción"],a:2,e:"La incertidumbre sobre empresa en funcionamiento va en una sección propia, separada de los KAM.",r:"M4 · P135"},
{id:"M4-111",m:4,q:"\"Consolidación bajo IFRS 10: una controlante debe presentar estados consolidados salvo excepciones (inversión entidad, etc.)\". Esta afirmación es:",o:["Falsa: la consolidación es optativa","Verdadera","Falsa","Verdadera sólo si la controlada es del exterior"],a:1,e:"La regla es consolidar; las excepciones, como la entidad de inversión, están previstas en la propia norma.",r:"M4 · P136"},
{id:"M4-137",m:4,q:"El registro de Auditores Externos en Comisión Nacional de Valores es:",o:["Reservado (sólo lo consulta la CNV)","Privado (lo lleva cada Consejo Profesional)","Público (consultable en el sitio de la CNV)","Reservado, salvo pedido judicial"],a:2,e:"El registro es público: cualquiera lo consulta en el sitio web de la CNV.",r:"M4 · P137"}
);
